import javafx.application.Platform;import javafx.scene.media.*;import java.nio.file.*;
class AudioPlaybackTest {public static void main(String[] args){Platform.startup(()->{try{var media=new Media(Path.of(args[0]).toUri().toString());var player=new MediaPlayer(media);player.setVolume(0);player.setOnError(()->{System.err.println(player.getError());System.exit(1);});player.setOnPlaying(()->{System.out.println("PASS: JavaFX music reaches PLAYING, duration="+media.getDuration());player.stop();player.dispose();Platform.exit();});player.setOnReady(player::play);}catch(Exception e){e.printStackTrace();System.exit(1);}});}}
